/**
 * Config plugin: the seek bar draws AppCompat's own track and thumb.
 *
 * On Android 5+ AppCompat's style inherits from the system's, so a ROM could
 * turn the bar into a thick pill with no thumb. These are the same items
 * AppCompat uses below Android 5, where nothing comes from the system.
 *
 * android/ is in .gitignore and regenerated by prebuild, so this has to be a plugin.
 */
const { AndroidConfig, withAndroidStyles } = require('@expo/config-plugins');

const { assignStylesValue, getAppThemeGroup } = AndroidConfig.Styles;

const STYLE = { name: 'ResonusSeekBar', parent: 'android:Widget' };
const ITEMS = {
  'android:indeterminateOnly': 'false',
  'android:progressDrawable': '@drawable/abc_seekbar_track_material',
  'android:indeterminateDrawable': '@drawable/abc_seekbar_track_material',
  'android:thumb': '@drawable/abc_seekbar_thumb_material',
  'android:focusable': 'true',
  'android:paddingLeft': '16dip',
  'android:paddingRight': '16dip',
};

function assign(xml, parent, name, value) {
  return assignStylesValue(xml, { add: true, parent, name, value });
}

module.exports = function withFixedSeekBar(config) {
  return withAndroidStyles(config, (cfg) => {
    let xml = cfg.modResults;
    for (const [name, value] of Object.entries(ITEMS)) xml = assign(xml, STYLE, name, value);
    cfg.modResults = assign(xml, getAppThemeGroup(), 'seekBarStyle', `@style/${STYLE.name}`);
    return cfg;
  });
};
